window.RP_SESSION={"id":"S-98efe7b90cf0","messages":[{"id":"RP-III-0117291","time":"2026-07-04T22:07:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아, 보고서 다썼다. 나는 침대 위로 몸을 던졌다. 머리와 얼굴이 따로 놀아 정신이 아득한 와중에도 어찌저찌 제출까지 해내었다. 온 몸의 관절에 힘이 들어가지 않았다. 피곤했다.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0117292","time":"2026-07-04T22:12:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"신앙을 버려도 피곤해지는구나. 그 당연할 사실이 낯설게만 느껴졌다.\n 머리꼭지에서부터 여기 명치 까지가 엉킨 털실이 굴러다니는 듯 뒤숭숭한데, 졸리다. 약 기운 탓인가? 복용량을 늘리게 된지도 조금 되었다. 몸이 망가져가는 것에 두려움이 솟을 때도 괜찮았다. 라운데라님께서 옳은 길을 가게 해주실 것을 믿었고, 라운데라님을 믿는 스스로도 믿었다.\n 근데, 근데...","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0117293","time":"2026-07-04T22:13:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"일단 자고나서 생각하자. 피곤할 때 떠오르는 생각을 신용하지 말 것.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0117294","time":"2026-07-04T22:13:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0117295","time":"2026-07-04T22:13:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]},{"id":"RP-III-0117296","time":"2026-07-04T22:15:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 문제가 있다면, 사이먼이 그 이후 한동안 방에만 틀어박힌 채 하루 대부분의 시간을 잠으로 보내게 된 것.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0117297","time":"2026-07-04T22:15:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"진짜 핀.","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0117298","time":"2026-07-04T22:15:00+09:00","room":"RP III","name":"사이먼 피터 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3ea4affc20fd"]},{"id":"RP-III-0117299","time":"2026-07-04T22:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
